import type { Meta, StoryObj } from "@storybook/react-vite";

import { Accordion } from "../src/Accordion";

/**
 * Task 3.4 compound story — Accordion's parts (`Root`/`Item`/`Trigger`/
 * `Content`) composed as a consumer uses them: a single-open FAQ-style
 * disclosure list, rendered inline (no Portal, no forced-open state needed).
 */
