        </Accordion.Content>
      </Accordion.Item>
      <Accordion.Item value="billing">
        <Accordion.Trigger className="py-cog-3">How is usage billed?</Accordion.Trigger>
        <Accordion.Content className="pb-cog-3 text-body-sm text-cog-text-secondary">
          Per active workspace member, billed monthly.
        </Accordion.Content>
      </Accordion.Item>
    </Accordion.Root>
  ),
