import type { Meta, StoryObj } from "@storybook/react-vite";
import { useEffect, useState } from "react";

import { Button } from "../src/Button";

/**
 * Task 3.1 smoke story — ONE story only (3.3-3.5 own the 38-component
 * backlog). This is the proof-of-concept that `frontends/design-tokens/dist/
 * tokens.css` is a sufficient consumer stylesheet on its own: Button's
 * `primary` variant (frontends/ui/src/Button.tsx) resolves entirely from
 * LITERAL tokens.css custom properties —
 * `bg-cog-blue-600` / `text-white` at rest, `shadow-cog-glow-brand` (light)
 * / `shadow-cog-glow-brand-dark` (dark, via the `[data-theme="dark"]`
 * selector) on hover — with zero dependency on the theme-switchable
 * canvas/surface/text/border layer tokens.css intentionally does not emit
 * (see ../design-tokens/lib/emit-tokens-css.mjs). No MFE's hand-maintained
 * index.css is imported anywhere in this chain (see .storybook/preview.tsx).
 */
const meta = {
  title: "Smoke/Button",
  component: Button,
  parameters: { layout: "centered" },
} satisfies Meta<typeof Button>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Reflects the live `data-theme` attribute so the toolbar toggle's effect
 * is visible in the canvas, not just in devtools. */
function ThemeReadout() {
  const [theme, setTheme] = useState(
    () => document.documentElement.dataset.theme ?? "light",
  );

  useEffect(() => {
    const target = document.documentElement;
    const observer = new MutationObserver(() =>
      setTheme(target.dataset.theme ?? "light"),
    );
    observer.observe(target, { attributeFilter: ["data-theme"] });
    return () => observer.disconnect();
  }, []);

  return (
    <p className="text-body-sm text-cog-blue-700">
      data-theme: <strong>{theme}</strong> — hover the button; only the glow
      color changes (cog-shadow-glow-brand / -dark), both literal tokens.css
      values.
    </p>
  );
}

export const Primary: Story = {
  render: () => (
    <div className="flex flex-col items-center gap-cog-3">
      <Button variant="primary">Primary action</Button>
      <ThemeReadout />
    </div>
  ),
};


