--- frontends/ui/stories/Dialog.stories.tsx (168 lines) ---
import type { Meta, StoryObj } from "@storybook/react-vite";

import { Button } from "../src/Button";
import { Dialog } from "../src/Dialog";
import { Popover } from "../src/Popover";
import { Tooltip } from "../src/Tooltip";

/**
 * Task 3.4 compound story — ONE story per compound namespace (Task 3.2's
 * ruling): Dialog's five parts (`Root`/`Trigger`/`Title`/`Description`/
 * `Content`) are shown composed together as a consumer actually uses them,
 * not as five isolated part-stories.
 */
const meta = {
  title: "Compound/Dialog",
  component: Dialog.Root,
  parameters: { layout: "fullscreen" },
} satisfies Meta<typeof Dialog.Root>;

export default meta;
type Story = StoryObj<typeof meta>;

/** Ordinary single dialog, open by default so both themes are visible
 * without needing to click through the trigger. */
export const Default: Story = {
  render: () => (
    <div className="flex min-h-screen items-center justify-center bg-cog-canvas p-cog-6">
      <Dialog.Root defaultOpen>
        <Dialog.Trigger asChild>
          <Button variant="primary">Open dialog</Button>
        </Dialog.Trigger>
        <Dialog.Content closeLabel="Close">
          <div className="flex flex-col gap-cog-3 p-cog-5">
            <Dialog.Title className="text-heading-sm text-cog-text-primary">
              Delete workspace
            </Dialog.Title>
            <Dialog.Description className="text-body-sm text-cog-text-secondary">
              This removes the workspace and every board inside it. This
              cannot be undone.
            </Dialog.Description>
            <div className="flex justify-end gap-cog-2 pt-cog-2">
              <Button variant="secondary">Cancel</Button>
              <Button variant="primary">Delete</Button>
            </div>
          </div>
        </Dialog.Content>
      </Dialog.Root>
    </div>
  ),
};

/**
 * REQUIRED (Task 3.4 plan) — stacked-overlay z-band regression witness.
 *
 * `tailwind.preset.ts` `zIndex` bands, numerically: cog-dropdown(1000) <
 * cog-backdrop(1300) < cog-overlay(1301) < cog-popover-elevated(1400) <
 * cog-backdrop-elevated(1500) < cog-overlay-elevated(1501) < cog-toast(1600)
 * < cog-tooltip(1700).
 *
 * Two real defect shapes this demonstrates, both correctly resolved here:
 *
 * 1. A Popover opened FROM INSIDE a Dialog. Popover.Content's own default
 *    z-band is `z-cog-dropdown` (1000) — LOWER than the open Dialog's panel
 *    at `z-cog-overlay` (1301). Rendered unmodified, the popover would paint
 *    UNDERNEATH the dialog panel it visually opens from (both portal to
 *    `document.body`, so they're siblings in the same stacking context —
 *    numeric z-index compares directly). The "Faction picker" popover below
 *    passes `className="z-cog-popover-elevated"` (1400) to clear the dialog's
 *    1301 — the fix a caller must apply, and the thing this story exists to
 *    prove renders correctly.
 * 2. A second Dialog opened FROM the first (documented directly in
 *    Dialog.tsx's `overlayClassName` prop comment). Both dialogs' panels
 *    default to the SAME `z-cog-overlay` (1301), so the inner one wouldn't
 *    reliably stack above the outer. The "Confirm faction" dialog below
 *    passes `overlayClassName="z-cog-backdrop-elevated"` (1500) and its own
 *    `className="z-cog-overlay-elevated"` (1501) to clear the outer dialog
 *    by a full band.
 *
 * A Tooltip needs NO override anywhere in this stack: `z-cog-tooltip` (1700)
 * already sits above every other band in the system, including both
 * elevated ones, so it stays on top with its component defaults untouched.
 *
 * How a reviewer confirms correct ordering: each layer below is labelled
 * with its literal token name + numeric z-index and painted a distinct
 * translucent color, deliberately overlapped via inset offsets. If the
 * ordering were wrong (e.g. the popover NOT elevated), the dialog panel's
 * opaque surface would visibly cover the popover's corner instead of the
 * popover sitting on top of it — the bug is visible, not just asserted.
 */
export const StackedOverlays: Story = {
  render: () => (
    <div className="flex min-h-screen items-center justify-center bg-cog-canvas p-cog-8">
      <Dialog.Root defaultOpen>
        <Dialog.Trigger asChild>
          <Button variant="primary">Open outer dialog</Button>
        </Dialog.Trigger>
        <Dialog.Content closeLabel="Close outer dialog">
          <div className="flex flex-col gap-cog-4 p-cog-5">
            <Dialog.Title className="text-heading-sm text-cog-text-primary">
              Outer dialog — z-cog-overlay (1301)
            </Dialog.Title>
            <Dialog.Description className="text-body-sm text-cog-text-secondary">
              Two stacked overlay bugs are reproduced-and-fixed below: a
              popover opened from this dialog, and a second dialog opened
              from this dialog.
            </Dialog.Description>

            <Popover.Root defaultOpen>
              <Popover.Trigger asChild>
                <Button variant="secondary">Faction picker</Button>
              </Popover.Trigger>
              <Popover.Content
                className="z-cog-popover-elevated relative"
                sideOffset={8}
              >
                <p className="text-label font-semibold uppercase text-cog-blue-700">
                  z-cog-popover-elevated (1400)
                </p>
                <p className="mt-cog-1 text-body-sm text-cog-text-secondary">
                  Clears the outer dialog&apos;s z-cog-overlay (1301) — this
                  panel must render ON TOP of the dialog behind it.
                </p>

                <Tooltip.Provider>
                  <Tooltip.Root defaultOpen>
                    <Tooltip.Trigger asChild>
                      <Button variant="secondary" size="sm" className="mt-cog-3">
                        Hover target
                      </Button>
                    </Tooltip.Trigger>
                    <Tooltip.Content side="bottom" sideOffset={6}>
                      z-cog-tooltip (1700) — always topmost, no override
                      needed
                    </Tooltip.Content>
                  </Tooltip.Root>
                </Tooltip.Provider>
              </Popover.Content>
            </Popover.Root>

            <Dialog.Root defaultOpen>
              <Dialog.Trigger asChild>
                <Button variant="secondary">Confirm faction (inner dialog)</Button>
              </Dialog.Trigger>
              <Dialog.Content
                closeLabel="Close inner dialog"
                overlayClassName="z-cog-backdrop-elevated"
                className="z-cog-overlay-elevated"
              >
                <div className="flex flex-col gap-cog-3 p-cog-5">
                  <Dialog.Title className="text-heading-sm text-cog-text-primary">
                    Inner dialog — z-cog-overlay-elevated (1501)
                  </Dialog.Title>
                  <Dialog.Description className="text-body-sm text-cog-text-secondary">
                    Scrim on z-cog-backdrop-elevated (1500). Both bands clear
                    the outer dialog&apos;s 1300/1301 pair by a full storey —
                    the outer panel never shows through, and the outer surface
                    behind it dims a second time.
                  </Dialog.Description>
                </div>
              </Dialog.Content>
            </Dialog.Root>
          </div>
        </Dialog.Content>
      </Dialog.Root>
    </div>
  ),
};


