        <p className="px-cog-2 py-cog-1 text-body-sm font-semibold text-cog-text-primary">
          Jaime Rodriguez
        </p>
        <p className="px-cog-2 pb-cog-1 text-body-sm text-cog-text-secondary">
          Workspace admin — 12 boards
        </p>
      </HoverCard.Content>
    </HoverCard.Root>
  ),
};


