import type { Meta, StoryObj } from "@storybook/react-vite";
import { useState } from "react";

import { ShareCodeList } from "../src/sharecode/ShareCodeList";
import type {
  ShareCodeData,
  ShareCodeListController,
  ShareCodeListCopy,
} from "../src/sharecode/types";

const COPY: ShareCodeListCopy = {
  loading: "Loading invite codes…",
  loadError: "Couldn't load invite codes.",
  loadRetry: "Retry",
  emptyTitle: "No active invite codes",
  emptyBody: "Generate a code to let anyone in your org join this exercise.",
  generateCta: "Generate code",
  generateAnotherCta: "Generate another",
  revokeCta: "Revoke",
  activeStatus: "Active",
  generatedOn: ({ date }) => `Generated ${date}`,
  generatedBy: ({ name }) => `by ${name}`,
  maskedAriaLabel: "Invite code",
  reveal: "Reveal",
  hide: "Hide",
  copy: "Copy",
  copied: "Copied!",
  copyFailed: "Copy failed — select and copy manually.",
  actionError: "Something went wrong. Try again.",
  revokeConfirmTitle: "Revoke this invite code?",
  revokeConfirmBody:
    "Anyone holding this code loses the ability to join with it. This can't be undone.",
  revokeConfirmCta: "Revoke code",
  revokeConfirmCancel: "Cancel",
};

const INITIAL_CODES: readonly ShareCodeData[] = [
  {
    id: "code-1",
    code: "ORCA-4F2K-9QZX",
    created_at: "2026-08-12T00:00:00Z",
    byName: "Priya Patel",
  },
  {
    id: "code-2",
    code: "ORCA-7T1M-3LWV",
    created_at: "2026-08-28T00:00:00Z",
    byName: "Priya Patel",
  },
];

let nextGeneratedId = INITIAL_CODES.length + 1;

/**
 * In-memory stand-in for the real BFF-backed `useShareCodeList` hook, so
 * this story's Generate / Revoke read as working actions rather than static
 * chrome: Generate adds a row, Revoke opens the real confirm modal and
 * removes the row on confirm.
 */
function ShareCodeListDemo() {
  const [codes, setCodes] = useState(INITIAL_CODES);

  const controller: ShareCodeListController = {
    state: "ready",
    codes,
    reload: () => undefined,
    generate: async () => {
      const created: ShareCodeData = {
        id: `code-${nextGeneratedId++}`,
        code: "ORCA-NEW1-CODE",
        created_at: new Date().toISOString(),
        byName: "Priya Patel",
      };
      setCodes((prev) => [...prev, created]);
      return created;
    },
    revoke: async (id) => {
      setCodes((prev) => prev.filter((code) => code.id !== id));
    },
  };

  return (
    <div className="w-cog-modal">
      <ShareCodeList kind="org" controller={controller} copy={COPY} />
    </div>
  );
}

/**
 * Task 3.5 story — ShareCodeList (#332 multiple-codes), the shared
 * presentational multi-code invite surface reused by admin-mfe's ORG
 * visibility codes and shell-mfe's INDIVIDUAL personal codes. Shown here in
 * its "org" kind, ready state, with two active codes already generated.
 */
const meta = {
  title: "Components/ShareCodeList",
  component: ShareCodeList,
  parameters: { layout: "centered" },
} satisfies Meta<typeof ShareCodeList>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    kind: "org",
    controller: {
      state: "ready",
      codes: INITIAL_CODES,
      reload: () => undefined,
      generate: async () => INITIAL_CODES[0],
      revoke: async () => undefined,
    },
    copy: COPY,
  },
  render: () => <ShareCodeListDemo />,
};


