import type { Meta, StoryObj } from "@storybook/react-vite";
import { useState } from "react";

import { GripVertical } from "../src/icons";
import { SortableList, type SortableItemState } from "../src/SortableList";

interface SurveyQuestion {
  readonly id: string;
  readonly label: string;
}

const INITIAL_QUESTIONS: readonly SurveyQuestion[] = [
  { id: "q1", label: "What's your role on the team?" },
  { id: "q2", label: "How satisfied are you with onboarding?" },
  { id: "q3", label: "Any blockers this sprint?" },
  { id: "q4", label: "Rate this week's stand-up." },
];

function QuestionRow({
  question,
  position,
  state,
}: {
  readonly question: SurveyQuestion;
  readonly position: number;
  readonly state: SortableItemState;
}) {
  return (
    <div
      ref={state.setNodeRef}
      style={state.style}
      className={
        "flex items-center gap-cog-3 rounded-md border border-cog-border bg-cog-surface p-cog-3 " +
        (state.isGhost ? "opacity-40" : "")
      }
    >
      <button
        type="button"
        aria-label={`Reorder question ${position}: ${question.label}`}
        className="cursor-grab rounded-md p-cog-1 text-cog-text-tertiary hover:bg-cog-surface-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-cog-blue-600"
        {...state.handleProps}
      >
        <GripVertical aria-hidden="true" className="h-cog-4 w-cog-4" />
      </button>
      <span className="text-caption font-semibold text-cog-text-tertiary">
        Q{position}
      </span>
      <span className="text-body-sm text-cog-text-primary">
        {question.label}
      </span>
    </div>
  );
}

function SortableListDemo() {
  const [questions, setQuestions] = useState(INITIAL_QUESTIONS);

  return (
    <div className="flex w-cog-modal flex-col gap-cog-3">
      <p className="text-body-sm text-cog-text-secondary">
        Drag a row by its grip, or Tab to a grip and press Space/Enter to
        lift it, Arrow Up/Down to move, Space/Enter to drop, Escape to
        cancel.
      </p>
      <SortableList
        items={questions}
        getId={(question) => question.id}
        listLabel="Survey questions"
        dropLabel={(index) => `Drop here — becomes Q${index + 1}`}
        onReorder={(nextIds) => {
          const byId = new Map(questions.map((q) => [q.id, q]));
          setQuestions(
            nextIds
              .map((id) => byId.get(id))
              .filter((q): q is SurveyQuestion => q !== undefined),
          );
        }}
        renderItem={(question, state) => (
          <QuestionRow
            question={question}
            position={state.index + 1}
            state={state}
          />
        )}
      />
    </div>
  );
}

/**
 * Task 3.5 story — SortableList (#1281, Ask survey editor question
 * reordering). The primitive owns both reorder paths for real, so this
 * story wires them up rather than standing in for them:
 *   - Pointer: press-and-drag a row by its grip.
 *   - Keyboard: Tab to a grip, Space/Enter to lift, Arrow Up/Down to move,
 *     Space/Enter to drop, Escape to cancel — the component's ONE keyboard
 *     path (a bare arrow on a merely-focused grip is intentionally a no-op;
 *     see SortableList.tsx's own header comment). `reorderIds` is what
 *     `onReorder` receives already applied, so this demo just needs to
 *     re-key its local items by the returned id order.
 * `renderItem` mirrors ask-mfe's real `QuestionCard` chrome closely enough
 * to read as the actual consumer shape, not a synthetic stand-in.
 */
const meta = {
  title: "Components/SortableList",
  component: SortableList<SurveyQuestion>,
  parameters: { layout: "centered" },
} satisfies Meta<typeof SortableList<SurveyQuestion>>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    items: INITIAL_QUESTIONS,
    getId: (question) => question.id,
    onReorder: () => undefined,
    renderItem: (question, state) => (
      <QuestionRow
        question={question}
        position={state.index + 1}
        state={state}
      />
    ),
    listLabel: "Survey questions",
  },
  render: () => <SortableListDemo />,
};


