  revokeConfirmTitle: "Revoke this invite code?",
  revokeConfirmBody:
    "Anyone holding this code loses the ability to join with it. This can't be undone.",
  revokeConfirmCta: "Revoke code",
  revokeConfirmCancel: "Cancel",
};

const INITIAL_CODES: readonly ShareCodeData[] = [
  {
    id: "code-1",
    code: "ORCA-4F2K-9QZX",
    created_at: "2026-08-12T00:00:00Z",
    byName: "Priya Patel",
  },
  {
    id: "code-2",
    code: "ORCA-7T1M-3LWV",
    created_at: "2026-08-28T00:00:00Z",
    byName: "Priya Patel",
  },
];

let nextGeneratedId = INITIAL_CODES.length + 1;

/**
 * In-memory stand-in for the real BFF-backed `useShareCodeList` hook, so
 * this story's Generate / Revoke read as working actions rather than static
 * chrome: Generate adds a row, Revoke opens the real confirm modal and
 * removes the row on confirm.
 */
function ShareCodeListDemo() {
  const [codes, setCodes] = useState(INITIAL_CODES);

  const controller: ShareCodeListController = {
    state: "ready",
    codes,
    reload: () => undefined,
    generate: async () => {
      const created: ShareCodeData = {
        id: `code-${nextGeneratedId++}`,
        code: "ORCA-NEW1-CODE",
        created_at: new Date().toISOString(),
        byName: "Priya Patel",
      };
      setCodes((prev) => [...prev, created]);
      return created;
    },
    revoke: async (id) => {
      setCodes((prev) => prev.filter((code) => code.id !== id));
    },
  };

  return (
    <div className="w-cog-modal">
      <ShareCodeList kind="org" controller={controller} copy={COPY} />
    </div>
  );
}

/**
