import type { Meta, StoryObj } from "@storybook/react-vite";

import { ToastProvider, useToast } from "../src/toast-provider";
import { Button } from "../src/Button";

/**
 * The IMPERATIVE toast API — distinct from `Compound/Toast`, which is the
 * declarative Radix primitive. An MFE mounts this once at its entry point and
 * anything below it calls `useToast().success("…")` without rendering markup.
 *
 * Consolidated from three divergent per-MFE copies (studio, files, ask). The
 * two accessible names are injected via `copy` rather than imported, because
 * `ui` must not depend on platform-chrome's paraglide adapter — platform-chrome
 * already depends on `ui`, so that import would close a require cycle.
 *
 * Toasts are portaled to `document.body` and stack bottom-right, so these
 * stories use a full-screen layout and drive them from real buttons: the
 * viewport is fixed-position and only renders once something is queued.
 */
const meta = {
  title: "Compound/ToastProvider",
  component: ToastProvider,
  parameters: { layout: "fullscreen" },
} satisfies Meta<typeof ToastProvider>;

export default meta;
type Story = StoryObj<typeof meta>;

const COPY = {
  notificationsAria: "Notifications",
  dismissAria: "Dismiss",
};

function KindDemo(): React.JSX.Element {
  const toast = useToast();
  return (
    <div className="flex min-h-screen flex-col items-start gap-cog-3 bg-cog-canvas p-cog-6">
      <p className="text-body-sm text-cog-text-secondary">
        Each kind picks its own status surface, icon and live-region role —
        errors announce assertively via <code>role=&quot;alert&quot;</code> and
        linger longer (7s) than success/info (4s).
      </p>
      <div className="flex flex-wrap gap-cog-2">
        <Button onClick={() => toast.success("Profile saved.")}>Success</Button>
        <Button variant="secondary" onClick={() => toast.info("Rendering preview…")}>
          Info
        </Button>
        <Button variant="danger" onClick={() => toast.error("Upload failed — retry?")}>
          Error
        </Button>
      </div>
    </div>
  );
}

/** The three kinds, fired from real buttons. */
export const Default: Story = {
  render: () => (
    <ToastProvider copy={COPY}>
      <KindDemo />
    </ToastProvider>
  ),
};

function ActionDemo(): React.JSX.Element {
  const toast = useToast();
  return (
    <div className="flex min-h-screen flex-col items-start gap-cog-3 bg-cog-canvas p-cog-6">
      <p className="text-body-sm text-cog-text-secondary">
        An optional action button (the undo affordance) sits before Dismiss and
        closes the toast once invoked. <code>durationMs: 0</code> disables
        auto-dismiss entirely, so a destructive action stays until answered.
      </p>
      <Button
        onClick={() =>
          toast.success("Document moved to trash.", {
            durationMs: 0,
            actionLabel: "Undo",
            action: () => toast.info("Restored."),
          })
        }
      >
        Delete with undo
      </Button>
    </div>
  );
}

/** Action button + `durationMs: 0` (no auto-dismiss). */
export const WithAction: Story = {
  render: () => (
    <ToastProvider copy={COPY}>
      <ActionDemo />
    </ToastProvider>
  ),
};

function StackDemo(): React.JSX.Element {
  const toast = useToast();
  return (
    <div className="flex min-h-screen flex-col items-start gap-cog-3 bg-cog-canvas p-cog-6">
      <p className="text-body-sm text-cog-text-secondary">
        Toasts stack bottom-right in arrival order and each keeps its own timer,
        so a later success can outlive an earlier error.
      </p>
      <Button
        onClick={() => {
          toast.info("Queued 3 uploads.");
          toast.error("photo-2.png exceeded the size limit.");
          toast.success("photo-1.png uploaded.");
        }}
      >
        Fire three at once
      </Button>
    </div>
  );
}

/** Several toasts stacked, each on an independent timer. */
export const Stacked: Story = {
  render: () => (
    <ToastProvider copy={COPY}>
      <StackDemo />
    </ToastProvider>
  ),
};


